INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(42040, 417, 1, '<td valign="top">Crisp and blurred at the same time.  The cars look cool,  but the rest is lacking.</td>', 'Crisp and blurred at the same time.  The cars look cool,  but the rest is lacking.', '2002-03-25 07:11:00.000000', NULL, 1),
(42041, 417, 346, '<td valign="top">Great photo, but wishthat everything else had been in focus. Beautiful use of B&amp;W</td>', 'Great photo, but wishthat everything else had been in focus. Beautiful use of B&W', '2002-03-25 08:52:00.000000', NULL, 1),
(42042, 417, 325, '<td valign="top">Nicely done, I would have knocked you down for the blur, but the title says it all.  The blur gives it a nice evocative feeling, it makes me feel like it''s the end of a long, long day and I''m just too tired to think, that picture perfectly captures my state of mind at that moment! Thankfully, I don''t have those moments anymore.</td>', 'Nicely done, I would have knocked you down for the blur, but the title says it all.  The blur gives it a nice evocative feeling, it makes me feel like it''s the end of a long, long day and I''m just too tired to think, that picture perfectly captures my state of mind at that moment! Thankfully, I don''t have those moments anymore.', '2002-03-25 15:19:00.000000', NULL, 1),
(42043, 417, 472, '<td valign="top">cool shot. but might have tried resting your camera on something??</td>', 'cool shot. but might have tried resting your camera on something??', '2002-03-27 10:49:00.000000', NULL, 1),
(42044, 417, 651, '<td valign="top">good</td>', 'good', '2002-03-28 17:02:00.000000', NULL, 1),
(42045, 417, 357, '<td valign="top">B&amp;W often works well for night shots, but I wonder if colour wouldn''t have helped distinguish outside from reflections.</td>', 'B&W often works well for night shots, but I wonder if colour wouldn''t have helped distinguish outside from reflections.', '2002-03-31 00:08:00.000000', NULL, 1),
(42046, 417, 138, '<td valign="top">the b+w gave it the darkness effect..  the street lights in hoboken were some on, some off.. so that kinda sucked for color</td>', 'the b+w gave it the darkness effect..  the street lights in hoboken were some on, some off.. so that kinda sucked for color', '2002-04-15 09:21:00.000000', NULL, 0),
(42047, 423, 245, '<td valign="top">I wish this had been completely in focus, or less in focus!</td>', 'I wish this had been completely in focus, or less in focus!', '2002-03-25 00:07:00.000000', NULL, 1),
(42048, 423, 2, '<td valign="top">Very good subject and balance, but I''d like to have seen sharper focus on the condensation.</td>', 'Very good subject and balance, but I''d like to have seen sharper focus on the condensation.', '2002-03-25 08:15:00.000000', NULL, 1),
(42049, 423, 346, '<td valign="top">there doesn''t seem to be enough here to capture my attention. If it had been an even closer shot of the condensation, I would have liked it more.</td>', 'there doesn''t seem to be enough here to capture my attention. If it had been an even closer shot of the condensation, I would have liked it more.', '2002-03-25 08:53:00.000000', NULL, 1),
(42050, 423, 661, '<td valign="top">Good color contrasts.  Liked the picture.</td>', 'Good color contrasts.  Liked the picture.', '2002-03-25 13:20:00.000000', NULL, 1),
(42051, 423, 54, '<td valign="top">A bit blurry, but I still like it.</td>', 'A bit blurry, but I still like it.', '2002-03-25 14:24:00.000000', NULL, 1),
(42052, 423, 325, '<td valign="top">This is a very beautiful photo, I knocked it down a point because I wish the water droplets had been in focus. I love the way the water takes on the shape of the lamp? behind the glass. Good composition and lighting.</td>', 'This is a very beautiful photo, I knocked it down a point because I wish the water droplets had been in focus. I love the way the water takes on the shape of the lamp? behind the glass. Good composition and lighting.', '2002-03-25 15:22:00.000000', NULL, 1),
(42053, 423, 509, '<td valign="top">very nice effect</td>', 'very nice effect', '2002-03-25 20:25:00.000000', NULL, 1),
(42054, 423, 472, '<td valign="top">great combo of colors and abstract composition!</td>', 'great combo of colors and abstract composition!', '2002-03-27 10:49:00.000000', NULL, 1),
(42055, 423, 361, '<td valign="top">I like the effect.</td>', 'I like the effect.', '2002-03-28 11:22:00.000000', NULL, 1),
(42056, 423, 651, '<td valign="top">Good thinking</td>', 'Good thinking', '2002-03-28 17:03:00.000000', NULL, 1),
(42057, 423, 718, '<td valign="top">ok I guess.  I like the colors but it just isn''t interesting to me.</td>', 'ok I guess.  I like the colors but it just isn''t interesting to me.', '2002-03-30 23:28:00.000000', NULL, 1),
(42058, 423, 357, '<td valign="top">I like the way the condensation gives shape to the lights.</td>', 'I like the way the condensation gives shape to the lights.', '2002-03-31 00:08:00.000000', NULL, 1),
(42059, 423, 139, '<td valign="top">I''m a sucker for water.  I love this.</td>', 'I''m a sucker for water.  I love this.', '2002-03-31 06:58:00.000000', NULL, 1),
(42060, 423, 720, '<td valign="top">Seems just a tad blurry (perhaps my monitor quality) but other than that, excellent idea.</td>', 'Seems just a tad blurry (perhaps my monitor quality) but other than that, excellent idea.', '2002-03-31 13:22:00.000000', NULL, 1),
(42061, 425, 193, '<td valign="top">Neat shot.  Concentrating on the domed tree cover on the right would make for a cool composure I think.</td>', 'Neat shot.  Concentrating on the domed tree cover on the right would make for a cool composure I think.', '2002-03-25 09:12:00.000000', NULL, 1),
(42062, 425, 459, '<td valign="top">Photo evokes feeling of just walking down the street at night in tungsten-like light. Ok, but the leading lines should lead to something.</td>', 'Photo evokes feeling of just walking down the street at night in tungsten-like light. Ok, but the leading lines should lead to something.', '2002-03-25 12:38:00.000000', NULL, 1),
(42063, 425, 325, '<td valign="top">Pretty cool, nice perspective, I like the color.  I would have like to have seen the shot with the sidewalk (right)side as the subject and then framed with the two trees closest to you. This shot looks like it is really two photos and you couldn''t decide which one to take, the parking lot side or the sidwalk, so you put them in the same photo.</td>', 'Pretty cool, nice perspective, I like the color.  I would have like to have seen the shot with the sidewalk (right)side as the subject and then framed with the two trees closest to you. This shot looks like it is really two photos and you couldn''t decide which one to take, the parking lot side or the sidwalk, so you put them in the same photo.', '2002-03-25 15:26:00.000000', NULL, 1),
(42064, 425, 1, '<td valign="top">A little bit of white balance could correct the ugly orange cast.</td>', 'A little bit of white balance could correct the ugly orange cast.', '2002-03-25 16:00:00.000000', NULL, 1),
(42065, 425, 2, '<td valign="top">Very nice, soft, mellow effect acheived with this shot.</td>', 'Very nice, soft, mellow effect acheived with this shot.', '2002-03-26 20:06:00.000000', NULL, 1),
(42066, 425, 472, '<td valign="top">nice and crisp. did u use a tripod?</td>', 'nice and crisp. did u use a tripod?', '2002-03-27 10:50:00.000000', NULL, 1),
(42067, 425, 156, '<td valign="top">love how the near trees look</td>', 'love how the near trees look', '2002-03-27 15:06:00.000000', NULL, 1),
(42068, 425, 624, '<td valign="top">pretty lighting and night street</td>', 'pretty lighting and night street', '2002-03-28 14:51:00.000000', NULL, 1),
(42069, 425, 651, '<td valign="top">Very good</td>', 'Very good', '2002-03-28 17:04:00.000000', NULL, 1),
(42070, 425, 718, '<td valign="top">Lacks something.  There doesn''t seem to be a lot of pizzaz in this one.</td>', 'Lacks something.  There doesn''t seem to be a lot of pizzaz in this one.', '2002-03-30 23:29:00.000000', NULL, 1),
(42071, 425, 139, '<td valign="top">I love underlit trees.</td>', 'I love underlit trees.', '2002-03-31 06:59:00.000000', NULL, 1),
(42085, 429, 245, '<td valign="top">cool idea but the composition is a bit odd, it feels cramped</td>', 'cool idea but the composition is a bit odd, it feels cramped', '2002-03-25 00:08:00.000000', NULL, 1),
(42086, 429, 642, '<td valign="top">I still like it...a lot</td>', 'I still like it...a lot', '2002-03-25 01:16:00.000000', NULL, 1),
(42087, 429, 346, '<td valign="top">great abstract feel to this shot.</td>', 'great abstract feel to this shot.', '2002-03-25 08:55:00.000000', NULL, 1),
(42088, 429, 447, '<td valign="top">Nice colors!</td>', 'Nice colors!', '2002-03-25 09:46:00.000000', NULL, 1),
(42089, 429, 113, '<td valign="top">I think  this would have been a really great photo if the light at the bottom had been further underwater along with the metal.</td>', 'I think  this would have been a really great photo if the light at the bottom had been further underwater along with the metal.', '2002-03-25 12:28:00.000000', NULL, 1),
(42090, 429, 459, '<td valign="top">Volcanoish</td>', 'Volcanoish', '2002-03-25 12:41:00.000000', NULL, 1),
(42091, 429, 325, '<td valign="top">Beautiful color. I would have tried to use a slightly slower shutter speed to really capture the fountain water not fast enough to stop the motion but just fast enough to capture the water moving without fully blurring.  For my taste, the shutter speed allowed the water fountains to blur too much. Still this photo got high marks from me.</td>', 'Beautiful color. I would have tried to use a slightly slower shutter speed to really capture the fountain water not fast enough to stop the motion but just fast enough to capture the water moving without fully blurring.  For my taste, the shutter speed allowed the water fountains to blur too much. Still this photo got high marks from me.', '2002-03-25 15:31:00.000000', NULL, 1),
(42092, 429, 1, '<td valign="top">Lava looking water is pretty cool, but the image lacks something.</td>', 'Lava looking water is pretty cool, but the image lacks something.', '2002-03-25 20:16:00.000000', NULL, 1),
(42093, 429, 92, '<td valign="top">I *LOVE* this ! The color..the subject...it''s just a perfect picture. It certainly stirs thoughts ! Great job !</td>', 'I *LOVE* this ! The color..the subject...it''s just a perfect picture. It certainly stirs thoughts ! Great job !', '2002-03-26 13:40:00.000000', NULL, 1),
(42094, 429, 689, '<td valign="top">Would have been nice to see just the water and on a wider shot. The light has burned in a bit.</td>', 'Would have been nice to see just the water and on a wider shot. The light has burned in a bit.', '2002-03-26 16:02:00.000000', NULL, 1),
(42095, 429, 2, '<td valign="top">Photo is crooked, and I think it needs more balance on the sides/top -- but very good choice of subject.</td>', 'Photo is crooked, and I think it needs more balance on the sides/top -- but very good choice of subject.', '2002-03-26 20:08:00.000000', NULL, 1),
(42096, 429, 51, '<td valign="top">beautiful; nice colors, nice fraaming. the background with the plant is a little disappointing. but it can not be helped. great work.</td>', 'beautiful; nice colors, nice fraaming. the background with the plant is a little disappointing. but it can not be helped. great work.', '2002-03-27 10:46:00.000000', NULL, 1),
(42097, 429, 472, '<td valign="top">great shot!  only thing i would do diff is slightly rotate so that the fountain is more aligned with the horizontal axis.</td>', 'great shot!  only thing i would do diff is slightly rotate so that the fountain is more aligned with the horizontal axis.', '2002-03-27 10:50:00.000000', NULL, 1),
(42098, 429, 651, '<td valign="top">Good thinking</td>', 'Good thinking', '2002-03-28 17:05:00.000000', NULL, 1),
(42099, 429, 718, '<td valign="top">I like this one.  Great colors in the water.</td>', 'I like this one.  Great colors in the water.', '2002-03-30 23:30:00.000000', NULL, 1),
(42100, 429, 139, '<td valign="top">Thanks for all the compliments.  I agree with Mousie that it''s a bit cramped (vertically).  Someone STOLE the fountain the very next day, so I''m glad I didn''t wait to get the shots.</td>', 'Thanks for all the compliments.  I agree with Mousie that it''s a bit cramped (vertically).  Someone STOLE the fountain the very next day, so I''m glad I didn''t wait to get the shots.', '2002-04-02 14:51:00.000000', NULL, 0),
(42101, 430, 352, '<td valign="top">I like the perspective.</td>', 'I like the perspective.', '2002-03-25 00:16:00.000000', NULL, 1),
(42102, 430, 245, '<td valign="top">It''s a shame there''s that big square building behind the left half of the bridge!</td>', 'It''s a shame there''s that big square building behind the left half of the bridge!', '2002-03-25 03:13:00.000000', NULL, 1),
(42103, 430, 346, '<td valign="top">sorry about the earlier comment. I was looking at the pic on a bad monitor. GREAT SHOT!</td>', 'sorry about the earlier comment. I was looking at the pic on a bad monitor. GREAT SHOT!', '2002-03-25 08:56:00.000000', NULL, 1),
(42104, 430, 447, '<td valign="top">Would have liked to see more of the horizontal part of the bridge...</td>', 'Would have liked to see more of the horizontal part of the bridge...', '2002-03-25 09:47:00.000000', NULL, 1),
(42105, 430, 113, '<td valign="top">Would have liked to have seen more of the floor of the bridge.  Depth of field was a little off.</td>', 'Would have liked to have seen more of the floor of the bridge.  Depth of field was a little off.', '2002-03-25 12:31:00.000000', NULL, 1),
(42106, 430, 325, '<td valign="top">Nice photo and concept.  I like the color. I knocked off a couple of points because it''s slightly out of focus (very slight) and I wish the bridge had been more in the middle (up and down) of the composition. Maybe if you set the focus to infinity?</td>', 'Nice photo and concept.  I like the color. I knocked off a couple of points because it''s slightly out of focus (very slight) and I wish the bridge had been more in the middle (up and down) of the composition. Maybe if you set the focus to infinity?', '2002-03-25 15:33:00.000000', NULL, 1),
(42107, 430, 509, '<td valign="top">nice composition</td>', 'nice composition', '2002-03-25 20:26:00.000000', NULL, 1),
(42108, 430, 641, '<td valign="top">Very cool... were you laying on the street to take this?</td>', 'Very cool... were you laying on the street to take this?', '2002-03-26 12:47:00.000000', NULL, 1),
(42109, 430, 2, '<td valign="top">Great shot!  I wish the lighting on the bar going up to the top right was as balanced as the left side, but what can ya do? :)</td>', 'Great shot!  I wish the lighting on the bar going up to the top right was as balanced as the left side, but what can ya do? :)', '2002-03-26 20:09:00.000000', NULL, 1),
(42110, 430, 472, '<td valign="top">cool symmettry.  were you lying on the floor?</td>', 'cool symmettry.  were you lying on the floor?', '2002-03-27 10:51:00.000000', NULL, 1),
(42111, 430, 156, '<td valign="top">like the ground level perspective</td>', 'like the ground level perspective', '2002-03-27 15:08:00.000000', NULL, 1),
(42112, 430, 624, '<td valign="top">good texture and lighting of bride, the positioning of the bridge too low for the entirety of the frame.</td>', 'good texture and lighting of bride, the positioning of the bridge too low for the entirety of the frame.', '2002-03-28 14:54:00.000000', NULL, 1),
(42113, 430, 441, '<td valign="top">interesting composition - very difficult to get a decent exposure with those lights.</td>', 'interesting composition - very difficult to get a decent exposure with those lights.', '2002-03-28 16:37:00.000000', NULL, 1),
(42114, 430, 651, '<td valign="top">Great shot</td>', 'Great shot', '2002-03-28 17:05:00.000000', NULL, 1),
(42115, 430, 139, '<td valign="top">This is great!  I think I would have liked it better angled slightly more downward.  I''m bothered not being able to see any of the ground at all.</td>', 'This is great!  I think I would have liked it better angled slightly more downward.  I''m bothered not being able to see any of the ground at all.', '2002-03-31 07:00:00.000000', NULL, 1),
(42116, 431, 245, '<td valign="top">Can you do flash compensation on your camera? if you can, try using a dimmer flash. Perhaps a flash and then a longer exposure to get more ofthe background could be cool!</td>', 'Can you do flash compensation on your camera? if you can, try using a dimmer flash. Perhaps a flash and then a longer exposure to get more ofthe background could be cool!', '2002-03-25 00:10:00.000000', NULL, 1),
(42117, 431, 352, '<td valign="top">The grass under the tree is a bit washed out, but this is an amazing shot!</td>', 'The grass under the tree is a bit washed out, but this is an amazing shot!', '2002-03-25 00:18:00.000000', NULL, 1),
(42118, 431, 193, '<td valign="top">I like the nature - industry contrast.</td>', 'I like the nature - industry contrast.', '2002-03-25 09:15:00.000000', NULL, 1),
(42119, 431, 113, '<td valign="top">Very nice.  Did a great job of setting this up  What''s the thing hanging in the bush.  Takes away from the photo.</td>', 'Very nice.  Did a great job of setting this up  What''s the thing hanging in the bush.  Takes away from the photo.', '2002-03-25 12:33:00.000000', NULL, 1),
(42120, 431, 459, '<td valign="top">Great idea with the blooming bushes in the foreground.  Should lose the stones in the foreground and get more light on the chimney.</td>', 'Great idea with the blooming bushes in the foreground.  Should lose the stones in the foreground and get more light on the chimney.', '2002-03-25 12:44:00.000000', NULL, 1),
(42121, 431, 142, '<td valign="top">Attractive photo.  Is that the Washington Monument?</td>', 'Attractive photo.  Is that the Washington Monument?', '2002-03-25 13:38:00.000000', NULL, 1),
(42122, 431, 1, '<td valign="top">The Monument in the background is a nice touch, but the foreground doesn''t do much for me.</td>', 'The Monument in the background is a nice touch, but the foreground doesn''t do much for me.', '2002-03-25 14:29:00.000000', NULL, 1),
(42123, 431, 325, '<td valign="top">Pretty good this is actually a tricky shot, but I don''t like the color of the flash on the trees.  Maybe if the shutter speed was just a bit slower? A decent score but not high.</td>', 'Pretty good this is actually a tricky shot, but I don''t like the color of the flash on the trees.  Maybe if the shutter speed was just a bit slower? A decent score but not high.', '2002-03-25 15:34:00.000000', NULL, 1),
(42124, 431, 133, '<td valign="top">Creative and unique</td>', 'Creative and unique', '2002-03-26 05:37:00.000000', NULL, 1),
(42125, 431, 51, '<td valign="top">flash = bad</td>', 'flash = bad', '2002-03-26 12:46:00.000000', NULL, 1),
(42126, 431, 641, '<td valign="top">What type of tree is that? Very pretty trees</td>', 'What type of tree is that? Very pretty trees', '2002-03-26 12:47:00.000000', NULL, 1),
(42127, 431, 2, '<td valign="top">Without the flower bed providing the weak ground, this picture would have been a lot better.  Nice subject.</td>', 'Without the flower bed providing the weak ground, this picture would have been a lot better.  Nice subject.', '2002-03-26 20:10:00.000000', NULL, 1),
(42128, 431, 554, '<td valign="top">Really good capture of color and great focus.</td>', 'Really good capture of color and great focus.', '2002-03-26 20:16:00.000000', NULL, 1),
(42129, 431, 472, '<td valign="top">good composition. nice use of fill flash and mixed lighting.</td>', 'good composition. nice use of fill flash and mixed lighting.', '2002-03-27 10:51:00.000000', NULL, 1),
(42130, 431, 361, '<td valign="top">Like the color. (Where on earth do you live to have blooms already!?)</td>', 'Like the color. (Where on earth do you live to have blooms already!?)', '2002-03-28 11:37:00.000000', NULL, 1),
(42131, 431, 651, '<td valign="top">Good</td>', 'Good', '2002-03-28 17:06:00.000000', NULL, 1),
(42132, 431, 543, '<td valign="top">Bonus point for being in D.C.  Is that flash on the trees?  Might have been better to tone it down a bit to get more exposure on George back there.  Nice work.</td>', 'Bonus point for being in D.C.  Is that flash on the trees?  Might have been better to tone it down a bit to get more exposure on George back there.  Nice work.', '2002-03-29 06:15:00.000000', NULL, 1),
(42133, 431, 139, '<td valign="top">I like the contrast here.  This is one of those images that grows on me.</td>', 'I like the contrast here.  This is one of those images that grows on me.', '2002-03-31 07:01:00.000000', NULL, 1),
(42134, 432, 245, '<td valign="top">nothing''s in focus, but it''s attractive. :)</td>', 'nothing''s in focus, but it''s attractive. :)', '2002-03-25 00:10:00.000000', NULL, 1),
(42135, 432, 113, '<td valign="top">Would have liked to see things  a lot sharper.</td>', 'Would have liked to see things  a lot sharper.', '2002-03-25 12:35:00.000000', NULL, 1),
(42136, 432, 54, '<td valign="top">A person in the room or something going on would give it more interest. Neat idea.</td>', 'A person in the room or something going on would give it more interest. Neat idea.', '2002-03-25 14:33:00.000000', NULL, 1),
(42137, 432, 1, '<td valign="top">Interesting take on things, though either very blurry or out of focus.</td>', 'Interesting take on things, though either very blurry or out of focus.', '2002-03-25 14:54:00.000000', NULL, 1),
(42138, 432, 325, '<td valign="top">Okay photo, I just wish something was in focus. I think the distance, color, and composition is decent.</td>', 'Okay photo, I just wish something was in focus. I think the distance, color, and composition is decent.', '2002-03-25 15:35:00.000000', NULL, 1),
(42139, 432, 509, '<td valign="top">A bit blurry, the subject seems lacking</td>', 'A bit blurry, the subject seems lacking', '2002-03-25 20:27:00.000000', NULL, 1),
(42140, 432, 689, '<td valign="top">The idea is good, but nothing is in focus .. it might be from the shutter speed, so you might try using a tripod or leaning against something.</td>', 'The idea is good, but nothing is in focus .. it might be from the shutter speed, so you might try using a tripod or leaning against something.', '2002-03-26 16:06:00.000000', NULL, 1),
(42141, 432, 51, '<td valign="top">Excellent shot. Maybe a bit too blurry, but I like the colors and the arrangement.</td>', 'Excellent shot. Maybe a bit too blurry, but I like the colors and the arrangement.', '2002-03-27 10:43:00.000000', NULL, 1),
(42142, 432, 472, '<td valign="top">nice voyeuristic feel here ; )</td>', 'nice voyeuristic feel here ; )', '2002-03-27 10:51:00.000000', NULL, 1),
(42143, 432, 651, '<td valign="top">I like where you''re going with this..</td>', 'I like where you''re going with this..', '2002-03-28 17:06:00.000000', NULL, 1),
(42144, 432, 543, '<td valign="top">This is just defocused enough to be graphically interesting.  I keep playing around with different compositional possibilities, but you''ve hit some good stuff here - the lampshade taking up exactly two slots, the alignment of the picture frame in the blinds, etc.  Nicely done!</td>', 'This is just defocused enough to be graphically interesting.  I keep playing around with different compositional possibilities, but you''ve hit some good stuff here - the lampshade taking up exactly two slots, the alignment of the picture frame in the blinds, etc.  Nicely done!', '2002-03-29 06:17:00.000000', NULL, 1),
(42145, 432, 718, '<td valign="top">It looks like the camera may have gone off accidentaly on this one.  Or maybe somebody is trying to catch a neighbor in the act (if you know what I mean)</td>', 'It looks like the camera may have gone off accidentaly on this one.  Or maybe somebody is trying to catch a neighbor in the act (if you know what I mean)', '2002-03-30 23:31:00.000000', NULL, 1),
(42146, 432, 357, '<td valign="top">Interesting how the blinds give this a TV look.</td>', 'Interesting how the blinds give this a TV look.', '2002-03-31 00:10:00.000000', NULL, 1),
(42147, 432, 139, '<td valign="top">It''s interesting, but I think I would have liked it better shifted to the left.  Everything from the black beam and to the right seems inconsequential to the photo.</td>', 'It''s interesting, but I think I would have liked it better shifted to the left.  Everything from the black beam and to the right seems inconsequential to the photo.', '2002-03-31 07:03:00.000000', NULL, 1),
(42148, 434, 352, '<td valign="top">A bit grainy, but the contrast is good.</td>', 'A bit grainy, but the contrast is good.', '2002-03-25 00:20:00.000000', NULL, 1),
(42149, 434, 346, '<td valign="top">love the shadows playing on the building</td>', 'love the shadows playing on the building', '2002-03-25 08:57:00.000000', NULL, 1),
(42150, 434, 459, '<td valign="top">Very graphic !  Foreground trees add a lot.</td>', 'Very graphic !  Foreground trees add a lot.', '2002-03-25 11:54:00.000000', NULL, 1),
(42151, 434, 113, '<td valign="top">Great  building, good shadows.  Too darn bad you didn''t know about the next challenge.</td>', 'Great  building, good shadows.  Too darn bad you didn''t know about the next challenge.', '2002-03-25 12:36:00.000000', NULL, 1),
(42152, 434, 661, '<td valign="top">Nice shapes and shadows.</td>', 'Nice shapes and shadows.', '2002-03-25 13:22:00.000000', NULL, 1),
(42153, 434, 1, '<td valign="top">Looks like a cardboard cutout.  Pretty interesting image.</td>', 'Looks like a cardboard cutout.  Pretty interesting image.', '2002-03-25 14:59:00.000000', NULL, 1),
(42154, 434, 325, '<td valign="top">Nice shot. Great subject. I like way you captured the light and mood. I can''t decide if it''s spooky but the photo is very fascinating to look at. I don''t know if it''s easy but I would have changed the composition and it''s very slightly out of focus.</td>', 'Nice shot. Great subject. I like way you captured the light and mood. I can''t decide if it''s spooky but the photo is very fascinating to look at. I don''t know if it''s easy but I would have changed the composition and it''s very slightly out of focus.', '2002-03-25 15:37:00.000000', NULL, 1),
(42155, 434, 258, '<td valign="top">Looks like its out-of-focus</td>', 'Looks like its out-of-focus', '2002-03-25 18:17:00.000000', NULL, 1),
(42156, 434, 173, '<td valign="top">Very nice! Would have worked well for this weeks challenge too. Great cropping</td>', 'Very nice! Would have worked well for this weeks challenge too. Great cropping', '2002-03-26 18:40:00.000000', NULL, 1),
(42157, 434, 472, '<td valign="top">forbidding!</td>', 'forbidding!', '2002-03-27 10:52:00.000000', NULL, 1),
(42158, 434, 624, '<td valign="top">good subject, lighting however slightly off focus</td>', 'good subject, lighting however slightly off focus', '2002-03-28 14:57:00.000000', NULL, 1),
(42159, 434, 651, '<td valign="top">Nice trees</td>', 'Nice trees', '2002-03-28 17:07:00.000000', NULL, 1),
(42160, 434, 543, '<td valign="top">Nicely composed, and a good subject.  I can''t quite tell whether the focus is soft or if that''s just quality degradation from noise, but it''s far from bad regardless.  Nice work.</td>', 'Nicely composed, and a good subject.  I can''t quite tell whether the focus is soft or if that''s just quality degradation from noise, but it''s far from bad regardless.  Nice work.', '2002-03-29 06:19:00.000000', NULL, 1),
(42161, 434, 718, '<td valign="top">Not very sharp.</td>', 'Not very sharp.', '2002-03-30 23:32:00.000000', NULL, 1),
(42162, 434, 357, '<td valign="top">Great looming presence.</td>', 'Great looming presence.', '2002-03-31 00:10:00.000000', NULL, 1),
(42163, 434, 139, '<td valign="top">Great subject, nice choice of angle.</td>', 'Great subject, nice choice of angle.', '2002-03-31 07:03:00.000000', NULL, 1),
(42164, 438, 352, '<td valign="top">Nice composition, but the power line in the upper right is distracting.  This would be better without it.</td>', 'Nice composition, but the power line in the upper right is distracting.  This would be better without it.', '2002-03-25 00:21:00.000000', NULL, 1),
(42165, 438, 2, '<td valign="top">Great colors, especially for a night shot.</td>', 'Great colors, especially for a night shot.', '2002-03-25 08:17:00.000000', NULL, 1),
(42166, 438, 325, '<td valign="top">Very nice shot. Immediately liked it.  Plus it''s in focus, has great color, and the composition is decent. The wiring up in the corner, and the lights on the right are a bit distracting, one point for that, but I love the shadow of the tree on the building! High marks.</td>', 'Very nice shot. Immediately liked it.  Plus it''s in focus, has great color, and the composition is decent. The wiring up in the corner, and the lights on the right are a bit distracting, one point for that, but I love the shadow of the tree on the building! High marks.', '2002-03-25 15:39:00.000000', NULL, 1),
(42167, 438, 430, '<td valign="top">I didn''t know this was Josh''s house</td>', 'I didn''t know this was Josh''s house', '2002-03-25 18:37:00.000000', NULL, 1),
(42168, 438, 689, '<td valign="top">The photo is nice with the shadows and colors, but I am not sure what this is or what the photo is trying to tell me. Let the photo tell your story.</td>', 'The photo is nice with the shadows and colors, but I am not sure what this is or what the photo is trying to tell me. Let the photo tell your story.', '2002-03-26 16:09:00.000000', NULL, 1),
(42169, 438, 554, '<td valign="top">I like it. Really warm.  I wonder what it would have looked like with different settings of type of lighting.<br/>(incondescent, flourescent, etc)(WHITE BAL)</td>', 'I like it. Really warm.  I wonder what it would have looked like with different settings of type of lighting.(incondescent, flourescent, etc)(WHITE BAL)', '2002-03-26 20:20:00.000000', NULL, 1),
(42170, 438, 472, '<td valign="top">what a freaky place ...</td>', 'what a freaky place ...', '2002-03-27 10:52:00.000000', NULL, 1),
(42171, 438, 557, '<td valign="top">wow, i like it , nice shadow too :)</td>', 'wow, i like it , nice shadow too :)', '2002-03-27 22:49:00.000000', NULL, 1),
(42172, 438, 361, '<td valign="top">Nice, sharp photo.</td>', 'Nice, sharp photo.', '2002-03-28 11:53:00.000000', NULL, 1),
(42173, 438, 651, '<td valign="top">Nicely set up</td>', 'Nicely set up', '2002-03-28 17:07:00.000000', NULL, 1),
(42174, 438, 543, '<td valign="top">This seems to me to be composed backwards, with the interesting bit of the building upstaged by the dull, flat wall at R.  It does have a nice shadow on it, though.  Setting the white balance to match the light source would have helped.  Good subject.</td>', 'This seems to me to be composed backwards, with the interesting bit of the building upstaged by the dull, flat wall at R.  It does have a nice shadow on it, though.  Setting the white balance to match the light source would have helped.  Good subject.', '2002-03-29 06:21:00.000000', NULL, 1),
(42175, 438, 718, '<td valign="top">Very suspensful pic.  I like it</td>', 'Very suspensful pic.  I like it', '2002-03-30 23:32:00.000000', NULL, 1),
(42176, 438, 139, '<td valign="top">This is my favorite photo here.  I love the lighting, the shadows, the colors, and the angle.  Great job.</td>', 'This is my favorite photo here.  I love the lighting, the shadows, the colors, and the angle.  Great job.', '2002-03-31 07:04:00.000000', NULL, 1),
(42177, 441, 27, '<td valign="top">If not quite so grainy, perfect</td>', 'If not quite so grainy, perfect', '2002-03-25 07:15:00.000000', NULL, 1),
(42178, 441, 193, '<td valign="top">Finally a picture with a message.  Good job.</td>', 'Finally a picture with a message.  Good job.', '2002-03-25 09:16:00.000000', NULL, 1),
(42179, 441, 536, '<td valign="top">I really like the idea of this picture. I wish it were clearer so I could score it a bit higher. Nothing about it makes me think he''s cold. But that''s okay.</td>', 'I really like the idea of this picture. I wish it were clearer so I could score it a bit higher. Nothing about it makes me think he''s cold. But that''s okay.', '2002-03-25 10:35:00.000000', NULL, 1),
(42180, 441, 113, '<td valign="top">I really like the way the person''s sweater fades into the wall.  Almost as if  they are a part of the woodwork.  The only think I didn''t like about the pic was the flash glare.</td>', 'I really like the way the person''s sweater fades into the wall.  Almost as if  they are a part of the woodwork.  The only think I didn''t like about the pic was the flash glare.', '2002-03-25 12:41:00.000000', NULL, 1),
(42181, 441, 459, '<td valign="top">Well done. Graininess adds a lot to the pic.</td>', 'Well done. Graininess adds a lot to the pic.', '2002-03-25 13:01:00.000000', NULL, 1),
(42182, 441, 1, '<td valign="top">Slight noise (I know, I know).  A longer shutter speed could''ve lessened the noise.  Otherwise a very original idea, and  a good subject.</td>', 'Slight noise (I know, I know).  A longer shutter speed could''ve lessened the noise.  Otherwise a very original idea, and  a good subject.', '2002-03-25 14:35:00.000000', NULL, 1),
(42183, 441, 325, '<td valign="top">Good shot! Nicely done. You captured the mood very well on this one. Oh and by the way, I''m not dinging you for the noise in the picture. Very good composition, good lighting, and excellent artistry.</td>', 'Good shot! Nicely done. You captured the mood very well on this one. Oh and by the way, I''m not dinging you for the noise in the picture. Very good composition, good lighting, and excellent artistry.', '2002-03-25 15:41:00.000000', NULL, 1),
(42184, 441, 509, '<td valign="top">Try a lower ISO maybe.....there''s a lot of noise in the shadows, which I understand is normal with night photography, but there this picture has the most noise out of the bunch.</td>', 'Try a lower ISO maybe.....there''s a lot of noise in the shadows, which I understand is normal with night photography, but there this picture has the most noise out of the bunch.', '2002-03-25 20:29:00.000000', NULL, 1),
(42185, 441, 443, '<td valign="top">Good juxtaposition with the magazines.</td>', 'Good juxtaposition with the magazines.', '2002-03-26 05:53:00.000000', NULL, 1),
(42186, 441, 173, '<td valign="top">Great photo for capturing tough reality</td>', 'Great photo for capturing tough reality', '2002-03-26 18:43:00.000000', NULL, 1),
(42187, 441, 2, '<td valign="top">Very moving picture, though the granularity of the photo is distracting.</td>', 'Very moving picture, though the granularity of the photo is distracting.', '2002-03-26 20:11:00.000000', NULL, 1),
(42188, 441, 330, '<td valign="top">I like the social comment made, but the figure could have been more defined. I know that may have been hard to do.  Joe</td>', 'I like the social comment made, but the figure could have been more defined. I know that may have been hard to do.  Joe', '2002-03-27 10:20:00.000000', NULL, 1),
(42189, 441, 472, '<td valign="top">i like photojournalistic stuff like this. gritty. how long was the exposure? in other words, did you stand here a long time?</td>', 'i like photojournalistic stuff like this. gritty. how long was the exposure? in other words, did you stand here a long time?', '2002-03-27 10:53:00.000000', NULL, 1),
(42190, 441, 554, '<td valign="top">I would have liked to have seen a little more of his upper body.  I liked it  though.</td>', 'I would have liked to have seen a little more of his upper body.  I liked it  though.', '2002-03-27 18:34:00.000000', NULL, 1),
(42191, 441, 557, '<td valign="top">nice composiition, and good idea</td>', 'nice composiition, and good idea', '2002-03-27 22:51:00.000000', NULL, 1),
(42192, 441, 361, '<td valign="top">Wish I could see the man a little better...</td>', 'Wish I could see the man a little better...', '2002-03-28 11:56:00.000000', NULL, 1),
(42193, 441, 624, '<td valign="top">very dramatic picture, very artistic, could be a painting.</td>', 'very dramatic picture, very artistic, could be a painting.', '2002-03-28 15:00:00.000000', NULL, 1),
(42194, 441, 651, '<td valign="top">Very Nice</td>', 'Very Nice', '2002-03-28 17:08:00.000000', NULL, 1),
(42195, 441, 603, '<td valign="top">powerful image..a little taste about the harsh more real aspects of nightlife..</td>', 'powerful image..a little taste about the harsh more real aspects of nightlife..', '2002-03-30 17:30:00.000000', NULL, 1),
(42196, 441, 718, '<td valign="top">Great Pic!  This one definately tells a thousand words!</td>', 'Great Pic!  This one definately tells a thousand words!', '2002-03-30 23:33:00.000000', NULL, 1),
(42197, 441, 139, '<td valign="top">I think this is one of the better subjects.</td>', 'I think this is one of the better subjects.', '2002-03-31 07:05:00.000000', NULL, 1),
(42198, 441, 543, '<td valign="top">I''m a bit surprised to see this much noise out of a D1X.  Is this an extreme crop from a larger image?</td>', 'I''m a bit surprised to see this much noise out of a D1X.  Is this an extreme crop from a larger image?', '2002-04-01 04:58:00.000000', NULL, 0),
(42199, 442, 245, '<td valign="top">I tried to capture sprinklers a bunch of different ways, you did a much better job! :)</td>', 'I tried to capture sprinklers a bunch of different ways, you did a much better job! :)', '2002-03-25 00:12:00.000000', NULL, 1),
(42200, 442, 113, '<td valign="top">Looks like a bunch of spacecraft have landed.  Nice photo.</td>', 'Looks like a bunch of spacecraft have landed.  Nice photo.', '2002-03-25 12:43:00.000000', NULL, 1),
(42201, 442, 142, '<td valign="top">Nice technique.  I like how you captured the light on the sprinklers.</td>', 'Nice technique.  I like how you captured the light on the sprinklers.', '2002-03-25 13:40:00.000000', NULL, 1),
(42202, 442, 325, '<td valign="top">An okay photo, it''s cool to look at, the low angle was a good idea, I hope it wasn''t too wet down there. But I think you had 4-5 subjects in this photo, I think if you''d picked just one, it would been an excellent photo! The scene has a lot of potential.</td>', 'An okay photo, it''s cool to look at, the low angle was a good idea, I hope it wasn''t too wet down there. But I think you had 4-5 subjects in this photo, I think if you''d picked just one, it would been an excellent photo! The scene has a lot of potential.', '2002-03-25 15:45:00.000000', NULL, 1),
(42203, 442, 92, '<td valign="top">So much goes on in the darkness. This captures that. It''s a great shot !</td>', 'So much goes on in the darkness. This captures that. It''s a great shot !', '2002-03-26 13:41:00.000000', NULL, 1),
(42204, 442, 689, '<td valign="top">Photo is good ... the composition is lacking with the building being cut off on the left.</td>', 'Photo is good ... the composition is lacking with the building being cut off on the left.', '2002-03-26 16:12:00.000000', NULL, 1),
(42205, 442, 554, '<td valign="top">Would make a good architech shot too.  I like it a lot</td>', 'Would make a good architech shot too.  I like it a lot', '2002-03-26 20:22:00.000000', NULL, 1),
(42206, 442, 472, '<td valign="top">great lighting!</td>', 'great lighting!', '2002-03-27 10:53:00.000000', NULL, 1),
(42207, 442, 651, '<td valign="top">Good</td>', 'Good', '2002-03-28 17:09:00.000000', NULL, 1),
(42208, 442, 718, '<td valign="top">This is a great one.  Very interesting.</td>', 'This is a great one.  Very interesting.', '2002-03-30 23:33:00.000000', NULL, 1),
(42209, 442, 357, '<td valign="top">Cool effect, but I think the building to the left is the most interesting thing here.  Could you have put that behind the sprinklers?</td>', 'Cool effect, but I think the building to the left is the most interesting thing here.  Could you have put that behind the sprinklers?', '2002-03-31 00:11:00.000000', NULL, 1),
(42210, 442, 139, '<td valign="top">The cylindrical building intrigues me to the point of distracting me from the sprinklers.  Did you take any shots where that building was the subject?</td>', 'The cylindrical building intrigues me to the point of distracting me from the sprinklers.  Did you take any shots where that building was the subject?', '2002-03-31 07:08:00.000000', NULL, 1),
(42211, 443, 113, '<td valign="top">Except for the streetlights......</td>', 'Except for the streetlights......', '2002-03-25 12:44:00.000000', NULL, 1),
(42212, 443, 1, '<td valign="top">Without the building on the left, the image would be stronger.</td>', 'Without the building on the left, the image would be stronger.', '2002-03-25 14:55:00.000000', NULL, 1),
(42213, 443, 325, '<td valign="top">Good photo, I like the composition.  I would crop just a bit more ... if that''s possible, so that the subject doesn''t have so much space around it. But the photo strongly evokes emotions (no I''m not religious either), the building and the light in the background really add a lot. Didn''t ding for the noise in the photo.</td>', 'Good photo, I like the composition.  I would crop just a bit more ... if that''s possible, so that the subject doesn''t have so much space around it. But the photo strongly evokes emotions (no I''m not religious either), the building and the light in the background really add a lot. Didn''t ding for the noise in the photo.', '2002-03-25 15:48:00.000000', NULL, 1),
(42214, 443, 2, '<td valign="top">Frightening.</td>', 'Frightening.', '2002-03-26 20:11:00.000000', NULL, 1),
(42215, 443, 554, '<td valign="top">Very nice.Perfect framing and well balanced. Think of the street light as a star. Well, maybe not. Right season too.</td>', 'Very nice.Perfect framing and well balanced. Think of the street light as a star. Well, maybe not. Right season too.', '2002-03-26 20:27:00.000000', NULL, 1),
(42216, 443, 472, '<td valign="top">interesting subject choice.</td>', 'interesting subject choice.', '2002-03-27 10:54:00.000000', NULL, 1),
(42217, 443, 651, '<td valign="top">Good</td>', 'Good', '2002-03-28 17:10:00.000000', NULL, 1),
(42218, 443, 718, '<td valign="top">I don''t know.  This just isn''t interesting.  It''s kind of creepy.</td>', 'I don''t know.  This just isn''t interesting.  It''s kind of creepy.', '2002-03-30 23:34:00.000000', NULL, 1),
(42219, 444, 352, '<td valign="top">The rain/snow is too prevalent and very distracting.</td>', 'The rain/snow is too prevalent and very distracting.', '2002-03-25 00:24:00.000000', NULL, 1),
(42220, 444, 270, '<td valign="top">Nice use of what folks might consider a drawback.</td>', 'Nice use of what folks might consider a drawback.', '2002-03-25 01:33:00.000000', NULL, 1),
(42221, 444, 113, '<td valign="top">This is kinda kool.  Set up could have been better.</td>', 'This is kinda kool.  Set up could have been better.', '2002-03-25 12:46:00.000000', NULL, 1),
(42222, 444, 459, '<td valign="top">Beautiful effect, but cropping out the flashed earth in the foreground would improve photo tremendously.</td>', 'Beautiful effect, but cropping out the flashed earth in the foreground would improve photo tremendously.', '2002-03-25 13:06:00.000000', NULL, 1),
(42223, 444, 142, '<td valign="top">Interesting.  The effect would have been better though if you were a little closer to the headstones.</td>', 'Interesting.  The effect would have been better though if you were a little closer to the headstones.', '2002-03-25 13:42:00.000000', NULL, 1),
(42224, 444, 326, '<td valign="top">Interesting image looks like an oil painting :-) Great title!</td>', 'Interesting image looks like an oil painting :-) Great title!', '2002-03-25 14:25:00.000000', NULL, 1),
(42225, 444, 280, '<td valign="top">spooky</td>', 'spooky', '2002-03-25 14:51:00.000000', NULL, 1),
(42226, 444, 325, '<td valign="top">Do you have an S30 or something? This photo came out all right though, it''s very eery.  I like the headstone? right at the edge of the flash distance, it gives you that creepy feeling like they''re might be something there, or maybe it''s just your imagination, the tilted ground adds to the effect - very Blair Witch. Points for the composition even if it looks accidental, and the ground is in decent focus!</td>', 'Do you have an S30 or something? This photo came out all right though, it''s very eery.  I like the headstone? right at the edge of the flash distance, it gives you that creepy feeling like they''re might be something there, or maybe it''s just your imagination, the tilted ground adds to the effect - very Blair Witch. Points for the composition even if it looks accidental, and the ground is in decent focus!', '2002-03-25 15:51:00.000000', NULL, 1),
(42227, 444, 509, '<td valign="top">Interesting phenomena, but it doesn''t really make for a lasting impression, the flash seems undesirable</td>', 'Interesting phenomena, but it doesn''t really make for a lasting impression, the flash seems undesirable', '2002-03-25 20:32:00.000000', NULL, 1),
(42228, 444, 689, '<td valign="top">Not sure what this is ... if it is the snowflakes, the background is distracting.</td>', 'Not sure what this is ... if it is the snowflakes, the background is distracting.', '2002-03-26 16:13:00.000000', NULL, 1),
(42229, 444, 554, '<td valign="top">Do you know what ANY of this is? Kind of looks like a lady, being followed by a cross , walking across ice covered tundra with fallen trees. And of course, the Orbs, whatever the heck they are. I have never seen so many Orbs before. And these have such a varity of colors too. I must give a 10 for this one. You have come closer to having All of the Orbs in focus at the same time as I have ever seen.</td>', 'Do you know what ANY of this is? Kind of looks like a lady, being followed by a cross , walking across ice covered tundra with fallen trees. And of course, the Orbs, whatever the heck they are. I have never seen so many Orbs before. And these have such a varity of colors too. I must give a 10 for this one. You have come closer to having All of the Orbs in focus at the same time as I have ever seen.', '2002-03-26 20:40:00.000000', NULL, 1),
(42230, 444, 472, '<td valign="top">was your lens wet?  i''m curious.</td>', 'was your lens wet?  i''m curious.', '2002-03-27 10:54:00.000000', NULL, 1),
(42231, 444, 624, '<td valign="top">very artistic and imaginative, great colors and contrast</td>', 'very artistic and imaginative, great colors and contrast', '2002-03-28 15:03:00.000000', NULL, 1),
(42232, 444, 651, '<td valign="top">Nice</td>', 'Nice', '2002-03-28 17:11:00.000000', NULL, 1),
(42233, 444, 543, '<td valign="top">Looks like the falling snow caught your flash.  I actually find the top half more interesting than the bottom, and a better fit for your title.</td>', 'Looks like the falling snow caught your flash.  I actually find the top half more interesting than the bottom, and a better fit for your title.', '2002-03-29 06:22:00.000000', NULL, 1),
(42234, 444, 441, '<td valign="top">interesting pic'' - good result</td>', 'interesting pic'' - good result', '2002-03-29 15:56:00.000000', NULL, 1),
(42235, 448, 245, '<td valign="top">This totaly rocks! You''ve got not one but two different cool lighting effects... the shilouette with just a glint of goggles and and the sparks with exactly the right length exposure to draw a nice little curve... nice!</td>', 'This totaly rocks! You''ve got not one but two different cool lighting effects... the shilouette with just a glint of goggles and and the sparks with exactly the right length exposure to draw a nice little curve... nice!', '2002-03-25 00:15:00.000000', NULL, 1),
(42236, 448, 352, '<td valign="top">Like it!</td>', 'Like it!', '2002-03-25 00:25:00.000000', NULL, 1),
(42237, 448, 215, '<td valign="top">nice effect</td>', 'nice effect', '2002-03-25 07:25:00.000000', NULL, 1),
(42238, 448, 346, '<td valign="top">great back-lightin to silhouette the figure. Love the sparks flying off</td>', 'great back-lightin to silhouette the figure. Love the sparks flying off', '2002-03-25 09:14:00.000000', NULL, 1),
(42239, 448, 447, '<td valign="top">Excellent photo! You''ve captured the man perfectly!</td>', 'Excellent photo! You''ve captured the man perfectly!', '2002-03-25 09:50:00.000000', NULL, 1),
(42240, 448, 113, '<td valign="top">Very clear pic and  WOW, no noise!</td>', 'Very clear pic and  WOW, no noise!', '2002-03-25 12:47:00.000000', NULL, 1),
(42241, 448, 142, '<td valign="top">Nice picture.  Very original.</td>', 'Nice picture.  Very original.', '2002-03-25 13:44:00.000000', NULL, 1),
(42242, 448, 326, '<td valign="top">Very nice!!</td>', 'Very nice!!', '2002-03-25 14:17:00.000000', NULL, 1),
(42243, 448, 325, '<td valign="top">Good shot, I wish you could have gotten the guy to pose a bit, the composition is a slightly off.  But I like the silhouette, and the flame gives off a nice color.</td>', 'Good shot, I wish you could have gotten the guy to pose a bit, the composition is a slightly off.  But I like the silhouette, and the flame gives off a nice color.', '2002-03-25 15:52:00.000000', NULL, 1),
(42244, 448, 554, '<td valign="top">"Watch the arc" .  "I can''t anymore, my eyes hurt".<br/>Also remember---Never look directly at an elipse.<br/>GOOD JOB !!</td>', '"Watch the arc" .  "I can''t anymore, my eyes hurt".Also remember---Never look directly at an elipse.GOOD JOB !!', '2002-03-25 20:42:00.000000', NULL, 1),
(42245, 448, 92, '<td valign="top">Just one word...WOW !!!! I love the action ... the shadows, the colors...the subject...it''s all right on !!!!</td>', 'Just one word...WOW !!!! I love the action ... the shadows, the colors...the subject...it''s all right on !!!!', '2002-03-26 13:42:00.000000', NULL, 1),
(42246, 448, 2, '<td valign="top">Great detail and focus -- excellent job with your camera settings for this shot.</td>', 'Great detail and focus -- excellent job with your camera settings for this shot.', '2002-03-26 20:12:00.000000', NULL, 1),
(42247, 448, 472, '<td valign="top">excellent image.  very good color and composition.</td>', 'excellent image.  very good color and composition.', '2002-03-27 10:55:00.000000', NULL, 1),
