(42295, 452, 651, '<td valign="top">Nice statement.. Well thought out..</td>', 'Nice statement.. Well thought out..', '2002-03-28 17:13:00.000000', NULL, 1),
(42296, 452, 139, '<td valign="top">The trash in the foreground is great, but the light and the lens flare are distracting.</td>', 'The trash in the foreground is great, but the light and the lens flare are distracting.', '2002-03-31 07:17:00.000000', NULL, 1),
(42297, 452, 705, '<td valign="top">a fine idea.  the trash in the foreground and the brightness of the light on the left are very distracting; the ''home'', I''m thinking, gets lost in these two elements; too much street; I love the colors though.  this is near Potrero Hill in SF, isn''t it?</td>', 'a fine idea.  the trash in the foreground and the brightness of the light on the left are very distracting; the ''home'', I''m thinking, gets lost in these two elements; too much street; I love the colors though.  this is near Potrero Hill in SF, isn''t it?', '2002-03-31 13:51:00.000000', NULL, 1),
(42298, 452, 357, '<td valign="top">I was very much in two minds about leaving the light flare, but decided to keep it because I wanted to emphasize the harsh aspect of the image.  Also, I wanted the composition to put more emphasis on the trash than the tents.<br/><br/>There is a UPS building off to the left with a very bright display screen showing the US flag on a regular basis; I really wanted to get it, but just couldn''t get everything to line up.</td>', 'I was very much in two minds about leaving the light flare, but decided to keep it because I wanted to emphasize the harsh aspect of the image.  Also, I wanted the composition to put more emphasis on the trash than the tents.There is a UPS building off to the left with a very bright display screen showing the US flag on a regular basis; I really wanted to get it, but just couldn''t get everything to line up.', '2002-04-02 16:00:00.000000', NULL, 0),
(42299, 453, 352, '<td valign="top">Great exposure.  Perfect shutter speed without getting any grain.  Good work!</td>', 'Great exposure.  Perfect shutter speed without getting any grain.  Good work!', '2002-03-25 00:27:00.000000', NULL, 1),
