(42392, 460, 705, '<td valign="top">ay, the timestamp is increidibly jarring-it''s all I can see unless I force myself to look at the rest, which is a interesting collection of curves; I like the effect.</td>', 'ay, the timestamp is increidibly jarring-it''s all I can see unless I force myself to look at the rest, which is a interesting collection of curves; I like the effect.', '2002-03-31 13:57:00.000000', NULL, 1),
(42393, 461, 245, '<td valign="top">I know you were trying for the reflections in the lake, but what about dropping the buildings to the bottom of the frame so you can see the vastness of space above them? It''d add to the lonliness!</td>', 'I know you were trying for the reflections in the lake, but what about dropping the buildings to the bottom of the frame so you can see the vastness of space above them? It''d add to the lonliness!', '2002-03-25 00:22:00.000000', NULL, 1),
(42394, 461, 346, '<td valign="top">I wish there had been more light reflecting on the water to get a better sense of what was going on in the foreground.</td>', 'I wish there had been more light reflecting on the water to get a better sense of what was going on in the foreground.', '2002-03-25 09:19:00.000000', NULL, 1),
