(42399, 461, 689, '<td valign="top">a vertictal shot of the lighthouse would have been nice with the reflection in the water ... the house on the left is dominating the photo with the over exposure of it.</td>', 'a vertictal shot of the lighthouse would have been nice with the reflection in the water ... the house on the left is dominating the photo with the over exposure of it.', '2002-03-26 16:18:00.000000', NULL, 1),
(42400, 461, 441, '<td valign="top">looks like you''ve shown up a lot of dead pixels on this shot - very long exposure?</td>', 'looks like you''ve shown up a lot of dead pixels on this shot - very long exposure?', '2002-03-29 16:10:00.000000', NULL, 1),
(42401, 461, 718, '<td valign="top">You should have put this baby through photoshop.  Cloned some of those nasty dots out of there.</td>', 'You should have put this baby through photoshop.  Cloned some of those nasty dots out of there.', '2002-03-30 23:39:00.000000', NULL, 1),
(42402, 461, 139, '<td valign="top">Great subject!</td>', 'Great subject!', '2002-03-31 07:22:00.000000', NULL, 1),
(42403, 461, 705, '<td valign="top">ah, the challenge of balancing the bright lights on the house with the dimmer light in the lighthouse.  ok composition, great foreground, although dim.</td>', 'ah, the challenge of balancing the bright lights on the house with the dimmer light in the lighthouse.  ok composition, great foreground, although dim.', '2002-03-31 13:58:00.000000', NULL, 1),
