(42411, 462, 472, '<td valign="top">ominous!</td>', 'ominous!', '2002-03-27 11:04:00.000000', NULL, 1),
(42412, 462, 139, '<td valign="top">I love cats at night.  I would take its collar off if you try this shot again in the future.</td>', 'I love cats at night.  I would take its collar off if you try this shot again in the future.', '2002-03-27 14:23:00.000000', NULL, 1),
(42413, 462, 325, '<td valign="top">I like the color of the eyes, decent focus, and composition.  I know it''s hard with a cat, but it would have been interesting if you had gotten a close up of the face, or tried for a low angle shot.</td>', 'I like the color of the eyes, decent focus, and composition.  I know it''s hard with a cat, but it would have been interesting if you had gotten a close up of the face, or tried for a low angle shot.', '2002-03-27 14:58:00.000000', NULL, 1),
