(42647, 494, 705, '<td valign="top">an interesting idea; the shoes are too shadowy on the side facing the camera; the lighted areas position throws me off; the footprints are distracting...the shoes are pointed the other way</td>', 'an interesting idea; the shoes are too shadowy on the side facing the camera; the lighted areas position throws me off; the footprints are distracting...the shoes are pointed the other way', '2002-03-31 14:19:00.000000', NULL, 1),
(42648, 495, 346, '<td valign="top">nice play of light.</td>', 'nice play of light.', '2002-03-25 11:04:00.000000', NULL, 1),
(42649, 495, 1, '<td valign="top">Looks a little slanted or un-centered.  Otherwise a nice idea.</td>', 'Looks a little slanted or un-centered.  Otherwise a nice idea.', '2002-03-25 14:46:00.000000', NULL, 1),
(42650, 495, 122, '<td valign="top">Its toodark to read in my opinion.</td>', 'Its toodark to read in my opinion.', '2002-03-26 00:42:00.000000', NULL, 1),
(42651, 495, 325, '<td valign="top">It looks like there''s all kind of photos in this one, but you put all of them in one shot. The subject of the photo is not clear to me from the composition or the angle of the photo. Nonetheless the lighting and shapes of the silhouette are very interesting. Maybe getting in closer or using fill flash with a slow sync flash would give a more complete photo.  You might also try cropping the black framing away to see what you get. Average marks.</td>', 'It looks like there''s all kind of photos in this one, but you put all of them in one shot. The subject of the photo is not clear to me from the composition or the angle of the photo. Nonetheless the lighting and shapes of the silhouette are very interesting. Maybe getting in closer or using fill flash with a slow sync flash would give a more complete photo.  You might also try cropping the black framing away to see what you get. Average marks.', '2002-03-26 16:10:00.000000', NULL, 1),
(42652, 495, 472, '<td valign="top">very homey<br/></td>', 'very homey', '2002-03-27 12:34:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(42653, 495, 447, '<td valign="top">Sort of busy, (a lot of things to look at) especially the detergent, which doesn''t fit in. But the pic on the whole works.</td>', 'Sort of busy, (a lot of things to look at) especially the detergent, which doesn''t fit in. But the pic on the whole works.', '2002-03-29 15:47:00.000000', NULL, 1),
(42654, 495, 718, '<td valign="top">Another Peeping Tom pic.</td>', 'Another Peeping Tom pic.', '2002-03-30 23:44:00.000000', NULL, 1),
(42655, 495, 705, '<td valign="top">the objects that are lit distract from those that aren''t; the objects that aren''t lit obscure those that are</td>', 'the objects that are lit distract from those that aren''t; the objects that aren''t lit obscure those that are', '2002-03-31 14:20:00.000000', NULL, 1),
(42656, 496, 459, '<td valign="top">Sparklers?</td>', 'Sparklers?', '2002-03-25 12:56:00.000000', NULL, 1),
(42657, 496, 142, '<td valign="top">I don''t really understand it.</td>', 'I don''t really understand it.', '2002-03-25 13:53:00.000000', NULL, 1),
(42658, 496, 637, '<td valign="top">huh?</td>', 'huh?', '2002-03-25 16:31:00.000000', NULL, 1),
(42659, 496, 325, '<td valign="top">Nice, very Lord of the Rings. This is a very tough shot to get right, but you did a good job, it is very evocative, I I like the circular effect. I can''t decide if it''s a face off or a marching parade, but I''m leaning more towards a face off of some type. Strong composition, great lighting, good job on getting that leading line despite all the movement. I like the way the glow on the ground mirrors the darkness above and everything seems to be floating in some sort of spirit world, like I said very Lord of the Rings, though third reich makes sense since Tolkien was influenced by WWI and WWII</td>', 'Nice, very Lord of the Rings. This is a very tough shot to get right, but you did a good job, it is very evocative, I I like the circular effect. I can''t decide if it''s a face off or a marching parade, but I''m leaning more towards a face off of some type. Strong composition, great lighting, good job on getting that leading line despite all the movement. I like the way the glow on the ground mirrors the darkness above and everything seems to be floating in some sort of spirit world, like I said very Lord of the Rings, though third reich makes sense since Tolkien was influenced by WWI and WWII', '2002-03-25 16:42:00.000000', NULL, 1),
(42660, 496, 2, '<td valign="top">The chaos in this picture is very well done.  Your jpeg compression is distracting, though.  Try saving at a higher quality.</td>', 'The chaos in this picture is very well done.  Your jpeg compression is distracting, though.  Try saving at a higher quality.', '2002-03-25 19:04:00.000000', NULL, 1),
(42661, 496, 689, '<td valign="top">Not sure what this is ....</td>', 'Not sure what this is ....', '2002-03-26 16:29:00.000000', NULL, 1),
(42662, 496, 554, '<td valign="top">Wild--------but I don''t know what it is.</td>', 'Wild--------but I don''t know what it is.', '2002-03-27 18:24:00.000000', NULL, 1),
(42663, 496, 624, '<td valign="top">unique, very good clarity and coloring. great imaginaton</td>', 'unique, very good clarity and coloring. great imaginaton', '2002-03-28 14:36:00.000000', NULL, 1),
(42664, 496, 447, '<td valign="top">Interesting, but what are we looking at?</td>', 'Interesting, but what are we looking at?', '2002-03-29 15:47:00.000000', NULL, 1),
