(42669, 497, 245, '<td valign="top">I''d center the sparkler for a more formal presentation, or try to make it obviously less formal... right now it''s somewhere in the middle and loses impact.</td>', 'I''d center the sparkler for a more formal presentation, or try to make it obviously less formal... right now it''s somewhere in the middle and loses impact.', '2002-03-25 03:18:00.000000', NULL, 1),
(42670, 497, 385, '<td valign="top">Give this a different title-it would be better</td>', 'Give this a different title-it would be better', '2002-03-25 09:24:00.000000', NULL, 1),
