(42685, 498, 352, '<td valign="top">Disturbing angle, but good composition.</td>', 'Disturbing angle, but good composition.', '2002-03-25 00:48:00.000000', NULL, 1),
(42686, 498, 2, '<td valign="top">Your angle and sharp contrast of light really give me a sense of height -- almost stomach-pulling.</td>', 'Your angle and sharp contrast of light really give me a sense of height -- almost stomach-pulling.', '2002-03-25 19:06:00.000000', NULL, 1),
(42687, 498, 122, '<td valign="top">I could be more essential if the tree were not there. Anyway I like the building pattern and the shadow of the flag on the wall.</td>', 'I could be more essential if the tree were not there. Anyway I like the building pattern and the shadow of the flag on the wall.', '2002-03-26 00:46:00.000000', NULL, 1),
(42688, 498, 113, '<td valign="top">Nice angle.</td>', 'Nice angle.', '2002-03-26 14:08:00.000000', NULL, 1),
(42689, 498, 689, '<td valign="top">Different perspective ...</td>', 'Different perspective ...', '2002-03-26 16:30:00.000000', NULL, 1),
(42690, 498, 472, '<td valign="top">good exposure but not an interesting subject, imo.  just being honest in hope it helps you</td>', 'good exposure but not an interesting subject, imo.  just being honest in hope it helps you', '2002-03-27 12:35:00.000000', NULL, 1),
(42691, 498, 312, '<td valign="top">This shot is *OKAY*. Would have been very cool without the tree and with a focus on that shadow flag.</td>', 'This shot is *OKAY*. Would have been very cool without the tree and with a focus on that shadow flag.', '2002-03-27 13:19:00.000000', NULL, 1),
(42692, 498, 361, '<td valign="top">I like the perspective!</td>', 'I like the perspective!', '2002-03-28 16:56:00.000000', NULL, 1),
(42693, 498, 543, '<td valign="top">A very interesting effect, but the flagpole kind of kills it.  Any way to shoot around it?  Great idea!</td>', 'A very interesting effect, but the flagpole kind of kills it.  Any way to shoot around it?  Great idea!', '2002-03-29 06:26:00.000000', NULL, 1),
(42694, 498, 447, '<td valign="top">The angle makes me fidget, but it is interesting nonetheless.</td>', 'The angle makes me fidget, but it is interesting nonetheless.', '2002-03-29 15:48:00.000000', NULL, 1),
(42695, 499, 352, '<td valign="top">I think there''s too much water in the foreground.  I find it takes my attention away from the subject.</td>', 'I think there''s too much water in the foreground.  I find it takes my attention away from the subject.', '2002-03-25 00:49:00.000000', NULL, 1),
(42696, 499, 459, '<td valign="top">I turned the brightness up on my monitor and now see the boat.  Cool</td>', 'I turned the brightness up on my monitor and now see the boat.  Cool', '2002-03-25 12:58:00.000000', NULL, 1),
(42697, 499, 54, '<td valign="top">A bit more focus needed, but still an interesting shot. Hmmm...you could be going for that foggy look the blurriness gives, though...</td>', 'A bit more focus needed, but still an interesting shot. Hmmm...you could be going for that foggy look the blurriness gives, though...', '2002-03-25 14:28:00.000000', NULL, 1),
(42698, 499, 325, '<td valign="top">Okay, but it''s so out of focus. If possible try to get the silhoutte with the lights directly behind/hidden by the boat.</td>', 'Okay, but it''s so out of focus. If possible try to get the silhoutte with the lights directly behind/hidden by the boat.', '2002-03-25 16:44:00.000000', NULL, 1),
(42699, 499, 92, '<td valign="top">Nice one ! I love the boat being in the shadows !</td>', 'Nice one ! I love the boat being in the shadows !', '2002-03-26 13:48:00.000000', NULL, 1),
(42700, 499, 113, '<td valign="top">I like your title, depicts the photo very well.</td>', 'I like your title, depicts the photo very well.', '2002-03-26 14:09:00.000000', NULL, 1),
(42701, 499, 689, '<td valign="top">Having more light behind the boat would have made it more the primary subject. The bright light is the first thing I am drawn to.</td>', 'Having more light behind the boat would have made it more the primary subject. The bright light is the first thing I am drawn to.', '2002-03-26 16:31:00.000000', NULL, 1),
(42702, 499, 472, '<td valign="top">interesting. altho i wish the left side was alittle lighter.  but that might have been hard wo completely blowing ou the lights.  very nice attempt tho : )</td>', 'interesting. altho i wish the left side was alittle lighter.  but that might have been hard wo completely blowing ou the lights.  very nice attempt tho : )', '2002-03-27 12:36:00.000000', NULL, 1),
(42703, 499, 447, '<td valign="top">Too dark! Too bad, looks like could have been a nice shot.</td>', 'Too dark! Too bad, looks like could have been a nice shot.', '2002-03-29 15:49:00.000000', NULL, 1),
(42704, 499, 705, '<td valign="top">too much foreground, the boat needs to be more dramatic; the haziness of focus works in the midground but not in the background</td>', 'too much foreground, the boat needs to be more dramatic; the haziness of focus works in the midground but not in the background', '2002-03-31 14:24:00.000000', NULL, 1),
(42705, 500, 270, '<td valign="top">Needs a judicious cropping job!</td>', 'Needs a judicious cropping job!', '2002-03-25 01:38:00.000000', NULL, 1),
(42706, 500, 459, '<td valign="top">Too much sky to do the pic justice.</td>', 'Too much sky to do the pic justice.', '2002-03-25 12:14:00.000000', NULL, 1),
(42707, 500, 142, '<td valign="top">Nice technique.</td>', 'Nice technique.', '2002-03-25 13:57:00.000000', NULL, 1),
(42708, 500, 325, '<td valign="top">Good clear shot, nice focus, but too much sky!</td>', 'Good clear shot, nice focus, but too much sky!', '2002-03-25 16:44:00.000000', NULL, 1),
(42709, 500, 245, '<td valign="top">The tower is just a touch blown out, but I love the composition.</td>', 'The tower is just a touch blown out, but I love the composition.', '2002-03-25 18:03:00.000000', NULL, 1),
(42710, 500, 689, '<td valign="top">A little overexposed at the top and the bottom of the courthouse is cut off.</td>', 'A little overexposed at the top and the bottom of the courthouse is cut off.', '2002-03-26 16:32:00.000000', NULL, 1),
(42711, 500, 624, '<td valign="top">good lighting, contrast of the light and building, great texture.</td>', 'good lighting, contrast of the light and building, great texture.', '2002-03-28 14:40:00.000000', NULL, 1),
(42712, 500, 447, '<td valign="top">Would have been great for this week''s challenge, no? I like it.</td>', 'Would have been great for this week''s challenge, no? I like it.', '2002-03-29 15:49:00.000000', NULL, 1),
(42713, 500, 705, '<td valign="top">good composition; the tower''s too hot; the tree in the foreground distracts</td>', 'good composition; the tower''s too hot; the tree in the foreground distracts', '2002-03-31 14:25:00.000000', NULL, 1),
(42714, 501, 245, '<td valign="top">this is totally freaky! it could stand a little contrast, though.</td>', 'this is totally freaky! it could stand a little contrast, though.', '2002-03-25 00:45:00.000000', NULL, 1),
(42715, 501, 346, '<td valign="top">too busy, not enough highlights.</td>', 'too busy, not enough highlights.', '2002-03-25 11:05:00.000000', NULL, 1),
(42716, 501, 536, '<td valign="top">I think it is harder to take pictures of objects like this at night than skylines and bridges.  Very good imo. Not sure how you got the feed a little out of focus.</td>', 'I think it is harder to take pictures of objects like this at night than skylines and bridges.  Very good imo. Not sure how you got the feed a little out of focus.', '2002-03-25 11:09:00.000000', NULL, 1),
(42717, 501, 459, '<td valign="top">The wheel and the "welcome" sign look great due to the nice diffused lighting.  I really like the whole shot .  I think i''ts the overall mood that gets me.  <br/></td>', 'The wheel and the "welcome" sign look great due to the nice diffused lighting.  I really like the whole shot .  I think i''ts the overall mood that gets me.  ', '2002-03-25 12:23:00.000000', NULL, 1),
(42718, 501, 661, '<td valign="top">Liked the old wheel.  Didn''t like the shaking bird house?</td>', 'Liked the old wheel.  Didn''t like the shaking bird house?', '2002-03-25 13:41:00.000000', NULL, 1),
(42719, 501, 325, '<td valign="top">Nice composition, very interesting and compelliing shot, needs a bit more exposure though, to get some details. The blurry bird box detracts from the overall picture. The low angle is really good for this photo.</td>', 'Nice composition, very interesting and compelliing shot, needs a bit more exposure though, to get some details. The blurry bird box detracts from the overall picture. The low angle is really good for this photo.', '2002-03-25 16:46:00.000000', NULL, 1),
(42720, 501, 2, '<td valign="top">Frightening subject and equally frightening lighting -- nicely done.</td>', 'Frightening subject and equally frightening lighting -- nicely done.', '2002-03-25 19:07:00.000000', NULL, 1),
(42721, 501, 1, '<td valign="top">I like this shot for reasons I can''t explain.  I just wish the little box in the top middle wasn''t blurred.  Shot looks like its from a G2?</td>', 'I like this shot for reasons I can''t explain.  I just wish the little box in the top middle wasn''t blurred.  Shot looks like its from a G2?', '2002-03-25 20:09:00.000000', NULL, 1),
(42722, 501, 472, '<td valign="top">very trippy surreal image. i like it.</td>', 'very trippy surreal image. i like it.', '2002-03-27 12:40:00.000000', NULL, 1),
(42723, 501, 312, '<td valign="top">This shot is a bit too dark and cluttered. Would have been better with the funky wheel thing as more of the primary focus.</td>', 'This shot is a bit too dark and cluttered. Would have been better with the funky wheel thing as more of the primary focus.', '2002-03-27 13:17:00.000000', NULL, 1),
(42724, 501, 554, '<td valign="top">I like a shot that says something----yours does.</td>', 'I like a shot that says something----yours does.', '2002-03-27 18:26:00.000000', NULL, 1),
(42725, 501, 447, '<td valign="top">What is the focus of the photo supposed to be? It is sort of busy and I find myself not sure what to look at.</td>', 'What is the focus of the photo supposed to be? It is sort of busy and I find myself not sure what to look at.', '2002-03-29 15:50:00.000000', NULL, 1),
(42726, 501, 255, '<td valign="top">This looks like something out of "Nightmare Before Christmas"! I like.</td>', 'This looks like something out of "Nightmare Before Christmas"! I like.', '2002-03-30 01:33:00.000000', NULL, 1),
(42727, 501, 91, '<td valign="top">very neat</td>', 'very neat', '2002-03-30 03:07:00.000000', NULL, 1),
(42728, 501, 705, '<td valign="top">busy, but my eye''s allowed to fix on the wheel, somehow; the foreground''s perfect somehow; there''s some problem with the ''welcome'' sign itself, maybe that it''s occluded by the wheel, or the hub</td>', 'busy, but my eye''s allowed to fix on the wheel, somehow; the foreground''s perfect somehow; there''s some problem with the ''welcome'' sign itself, maybe that it''s occluded by the wheel, or the hub', '2002-03-31 14:26:00.000000', NULL, 1),
(42729, 501, 270, '<td valign="top">Man -- I thought this shot was absolutely superb.  It would have won any Halloween contest.. good job, for sure!</td>', 'Man -- I thought this shot was absolutely superb.  It would have won any Halloween contest.. good job, for sure!', '2002-04-01 02:25:00.000000', NULL, 0),
(42730, 502, 245, '<td valign="top">attack of the flash monster!</td>', 'attack of the flash monster!', '2002-03-25 00:45:00.000000', NULL, 1),
(42731, 502, 459, '<td valign="top">The flash produced a lot of glare on the monsters.</td>', 'The flash produced a lot of glare on the monsters.', '2002-03-25 12:24:00.000000', NULL, 1),
(42732, 502, 325, '<td valign="top">This picture is okay, but it could be better. The good: the horizon is straight, the subject is in focus, and you have the right idea with the flash/slow sync shutter to capture the background. The bad: horizon is dead center, try a bit above and below center, subject is not obvious/confusing, try re-composing or getting closer to clarify subject.</td>', 'This picture is okay, but it could be better. The good: the horizon is straight, the subject is in focus, and you have the right idea with the flash/slow sync shutter to capture the background. The bad: horizon is dead center, try a bit above and below center, subject is not obvious/confusing, try re-composing or getting closer to clarify subject.', '2002-03-25 16:51:00.000000', NULL, 1),
(42733, 502, 472, '<td valign="top">your lens flare looks like the moon : ) .  i would like to have seen one of those boat things a lot closer and in not from the back but from a more interesting side.</td>', 'your lens flare looks like the moon : ) .  i would like to have seen one of those boat things a lot closer and in not from the back but from a more interesting side.', '2002-03-27 12:41:00.000000', NULL, 1),
(42734, 502, 624, '<td valign="top">fun! artsy, good coloring and thought</td>', 'fun! artsy, good coloring and thought', '2002-03-28 14:42:00.000000', NULL, 1),
(42735, 502, 91, '<td valign="top">heh that lens flare looks like the moon.  neat pic =)</td>', 'heh that lens flare looks like the moon.  neat pic =)', '2002-03-30 03:07:00.000000', NULL, 1),
(42736, 502, 705, '<td valign="top">such an imaginative title!  but the second ''moon'' is not convincing; lighting on the nessies is hard and unappealing; the centerpoint of the image is...unlocatable</td>', 'such an imaginative title!  but the second ''moon'' is not convincing; lighting on the nessies is hard and unappealing; the centerpoint of the image is...unlocatable', '2002-03-31 14:27:00.000000', NULL, 1),
(42737, 503, 245, '<td valign="top">i really like how you kept this picture dim, very nice</td>', 'i really like how you kept this picture dim, very nice', '2002-03-25 00:46:00.000000', NULL, 1),
(42738, 503, 102, '<td valign="top">Not an especially interesting shot, but the color is AWESOME. Really good color tones. Impressive.</td>', 'Not an especially interesting shot, but the color is AWESOME. Really good color tones. Impressive.', '2002-03-25 00:47:00.000000', NULL, 1),
(42739, 503, 459, '<td valign="top">Moody- induces kind of lonely feelings.</td>', 'Moody- induces kind of lonely feelings.', '2002-03-25 12:27:00.000000', NULL, 1),
(42740, 503, 1, '<td valign="top">Vibrant red in a dark alley makes for great composition.</td>', 'Vibrant red in a dark alley makes for great composition.', '2002-03-25 15:01:00.000000', NULL, 1),
(42741, 503, 549, '<td valign="top">I''d of picked this to win the red competiton!</td>', 'I''d of picked this to win the red competiton!', '2002-03-26 10:13:00.000000', NULL, 1),
(42742, 503, 92, '<td valign="top">I love the red ! It just adds so much to this shot !</td>', 'I love the red ! It just adds so much to this shot !', '2002-03-26 13:49:00.000000', NULL, 1),
(42743, 503, 325, '<td valign="top">Okay photo -  the good: in focus, interesting angle, nice depth, nice colors, i like the yin yang opposing effect of the darkness vs. the lighted areas - the bad: the composition is nice but it''s too far from subject, maybe try different/closer angles?</td>', 'Okay photo -  the good: in focus, interesting angle, nice depth, nice colors, i like the yin yang opposing effect of the darkness vs. the lighted areas - the bad: the composition is nice but it''s too far from subject, maybe try different/closer angles?', '2002-03-26 16:17:00.000000', NULL, 1),
(42744, 503, 216, '<td valign="top">Nice use of contrasting color</td>', 'Nice use of contrasting color', '2002-03-27 00:41:00.000000', NULL, 1),
